  try(TrackStore t=new TrackStore(getTargetContext())){check(t.diagnostics("2026-12-15").getJSONArray("rawPoints").toString().equals(snap.getJSONArray("raw").toString()),"Migration leaves raw GPS untouched");check(t.gpx("2026-12-15").equals(snap.getString("gpx")),"Migration leaves D/GPX unchanged");}
  check(queue().getInt("count")==0&&!queue().getJSONObject("settings").getBoolean("enabled"),"Upgrade does not queue all history or enable external calls");
  JSONObject r=(JSONObject)h.call("saveRecord",new JSONObject().put("record",note(id,"合成原始工作内容，未提供工时。")).put("allowDuplicate",true));long v=r.getLong("updatedAt");JSONArray old=queue().getJSONArray("jobs");
