  check(assigned.getLong("updatedAt")==v&&assigned.getString("note").equals(r.getString("note"))&&queue().getInt("count")==1,"Derived topic assignment preserves original/version and does not enqueue repeatedly");
  r=(JSONObject)h.call("saveRecord",new JSONObject().put("record",new JSONObject(r.toString()).put("note","合成编辑后的原文。")).put("allowDuplicate",true));check(r.getLong("updatedAt")>v,"Native content versions increase monotonically");
  h.call("ackWikiQueue",new JSONObject().put("jobs",old));check(queue().getInt("count")==1,"Old acknowledgement cannot clear edited queue version");
