  h.call("ackWikiQueue",new JSONObject().put("jobs",queue().getJSONArray("jobs")));h.call("deleteRecord",new JSONObject().put("id",id));h.call("ackWikiQueue",new JSONObject().put("jobs",queue().getJSONArray("jobs")));reload();mock();Thread.sleep(1800);
  jsCheck("__calls.length===0","Disabled automation makes zero model calls");jsCheck("document.querySelectorAll('.bottom-nav button').length===4","Four navigation entries remain");
  click("[data-page=chat]");h.js("document.querySelector('#chat-input').value='今天的工作：完成合成项目的测试清单，并写下下一步复盘内容。'");click("[data-action=send]");until("document.querySelector('[data-save-candidate]')!==null");
  jsCheck("document.querySelector('.candidate').innerText.includes('工作日志')","Narrative without working hours produces work-note candidate even if model returns empty");check(init().getJSONArray("records").length()==initial.getJSONArray("records").length(),"AI draft does not insert without confirmation");h.screenshot("agent-work-candidate-1.6.0.png");click("[data-save-candidate]");until("document.querySelector('[data-save-candidate]')===null");
  JSONArray rs=init().getJSONArray("records");JSONObject saved=null;for(int i=0;i<rs.length();i++)if(rs.getJSONObject(i).optString("note").startsWith("今天的工作：完成合成项目"))saved=rs.getJSONObject(i);check(saved!=null&&saved.getInt("durationMinutes")==0,"Confirm writes complete work narrative with zero invented hours");String rid=saved.getString("id");
  h.js("__mode='append';__target="+JSONObject.quote(rid)+";document.querySelector('#chat-input').value='追加工作日志，记录编号：'+__target+'，补充合成测试结论。'");click("[data-action=send]");until("document.querySelector('[data-confirm-change]')!==null");check(find(rid).getString("note").equals(saved.getString("note")),"Preparing append leaves original database untouched");click(".change-candidate details summary");h.screenshot("agent-update-preview-1.6.0.png");click("[data-confirm-change]");until("document.querySelector('[data-confirm-change]')===null");check(find(rid).getString("note").startsWith(saved.getString("note"))&&find(rid).getString("note").contains("合成追加"),"Confirmed append preserves original and writes new content");
  click("#open-settings");check(h.waitText("自动 Wiki 整理"),"Automation settings reachable");h.js("document.querySelector('#wiki-auto-enabled').checked=true;document.querySelector('#wiki-auto-form').requestSubmit()");until("document.querySelector('#confirm-dialog').open");click("#confirm-ok");until("__calls.some(p=>p.tool.name==='plan_wiki_topics')");until("__calls.some(p=>p.tool.name==='compile_learning_wiki')");for(int i=0;i<150&&queue().getInt("count")>0;i++)Thread.sleep(100);check(queue().getInt("count")==0,"Single opt-in automatically classifies and compiles saved work note");
  check(find(rid).getJSONArray("wikiTopics").getString(0).equals("合成项目"),"Automatic classification persisted to source record");JSONArray pages=init().getJSONArray("wikiPages");JSONObject p=null;for(int i=0;i<pages.length();i++)if(pages.getJSONObject(i).optString("topic").equals("合成项目"))p=pages.getJSONObject(i);check(p!=null&&p.getJSONArray("sourceIds").toString().contains(rid)&&p.getString("summary").contains("合成追加"),"Wiki compiles actual current source and stores traceable work-note references");
  h.js("document.querySelector('#wiki-auto-form').scrollIntoView({block:'center'})");h.screenshot("agent-auto-wiki-settings-1.6.0.png");
  // Simulate transient model failure, preserve native queue across WebView restart.
